package com.agentic.shortener.service;

import com.google.zxing.BinaryBitmap;
import com.google.zxing.RGBLuminanceSource;
import com.google.zxing.common.HybridBinarizer;
import com.google.zxing.qrcode.QRCodeReader;
import org.junit.jupiter.api.Test;
import org.w3c.dom.Document;

import javax.imageio.ImageIO;
import javax.xml.XMLConstants;
import javax.xml.parsers.DocumentBuilderFactory;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

public class QrCodeServiceTest {

    private static final String CONTENT = "http://short.test/abc1234";

    private final QrCodeService service = new QrCodeService();

    public static String decode(byte[] png) throws Exception {
        BufferedImage image = ImageIO.read(new ByteArrayInputStream(png));
        int[] pixels = image.getRGB(0, 0, image.getWidth(), image.getHeight(), null, 0, image.getWidth());
        var source = new RGBLuminanceSource(image.getWidth(), image.getHeight(), pixels);
        return new QRCodeReader().decode(new BinaryBitmap(new HybridBinarizer(source))).getText();
    }

    @Test
    void pngHasTheRequestedSizeAndDecodesBackToTheContent() throws Exception {
        byte[] png = service.png(CONTENT, 256);

        BufferedImage image = ImageIO.read(new ByteArrayInputStream(png));
        assertThat(image.getWidth()).isEqualTo(256);
        assertThat(image.getHeight()).isEqualTo(256);
        assertThat(decode(png)).isEqualTo(CONTENT);
    }

    @Test
    void pngStartsWithThePngSignature() {
        byte[] png = service.png(CONTENT, 128);
        assertThat(Arrays.copyOf(png, 8)).containsExactly(0x89, 'P', 'N', 'G', 0x0D, 0x0A, 0x1A, 0x0A);
    }

    @Test
    void theBoundarySizesWork() throws Exception {
        assertThat(decode(service.png(CONTENT, QrCodeService.MIN_SIZE))).isEqualTo(CONTENT);
        assertThat(decode(service.png(CONTENT, QrCodeService.MAX_SIZE))).isEqualTo(CONTENT);
    }

    @Test
    void svgIsWellFormedAndScalesToTheRequestedSize() throws Exception {
        String svg = service.svg(CONTENT, 320);

        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        Document doc = factory.newDocumentBuilder().parse(new ByteArrayInputStream(svg.getBytes(StandardCharsets.UTF_8)));
        assertThat(doc.getDocumentElement().getTagName()).isEqualTo("svg");
        assertThat(doc.getDocumentElement().getAttribute("width")).isEqualTo("320");
        assertThat(doc.getDocumentElement().getAttribute("height")).isEqualTo("320");
        assertThat(doc.getDocumentElement().getAttribute("viewBox")).matches("0 0 \\d+ \\d+");
        assertThat(doc.getElementsByTagName("path").item(0).getAttributes().getNamedItem("d").getNodeValue()).contains("h1v1h-1z");
    }

    @Test
    void theSameInputAlwaysGivesTheSameImage() {
        assertThat(service.png(CONTENT, 200)).isEqualTo(service.png(CONTENT, 200));
        assertThat(service.svg(CONTENT, 200)).isEqualTo(service.svg(CONTENT, 200));
    }

    @Test
    void differentContentGivesADifferentCode() {
        assertThat(service.svg("http://short.test/aaaaaaa", 200)).isNotEqualTo(service.svg("http://short.test/bbbbbbb", 200));
    }

    @Test
    void sizesOutsideTheSupportedRangeAreRejected() {
        assertThatThrownBy(() -> service.png(CONTENT, QrCodeService.MIN_SIZE - 1)).isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> service.png(CONTENT, QrCodeService.MAX_SIZE + 1)).isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> service.svg(CONTENT, 0)).isInstanceOf(IllegalArgumentException.class);
    }

    @Test
    void blankContentIsRejected() {
        assertThatThrownBy(() -> service.png(" ", 128)).isInstanceOf(IllegalArgumentException.class).hasMessageContaining("content");
        assertThatThrownBy(() -> service.svg(null, 128)).isInstanceOf(IllegalArgumentException.class);
    }
}

package com.agentic.shortener.web;

import com.agentic.IntegrationTest;
import com.agentic.shortener.service.QrCodeService;
import com.agentic.shortener.service.QrCodeServiceTest;
import com.agentic.shortener.service.ShortenerService;
import com.agentic.shortener.service.ShortenerService.CreateCommand;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import static org.assertj.core.api.Assertions.assertThat;
import static org.hamcrest.Matchers.containsString;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/** HTTP tests for QrController: formats, sizes and the 404 / 410 behaviour shared with the redirect. */
@AutoConfigureMockMvc
class QrControllerTest extends IntegrationTest {

    @Autowired
    MockMvc mvc;
    @Autowired
    ShortenerService service;

    private String newLink() {
        return service.create(new CreateCommand("https://example.com/page", null, null, null)).getShortCode();
    }

    @Test
    void pngByDefaultDecodesToTheShortUrl() throws Exception {
        String code = newLink();
        byte[] body = mvc.perform(get("/api/v1/urls/" + code + "/qr"))
                .andExpect(status().isOk())
                .andExpect(content().contentType(MediaType.IMAGE_PNG))
                .andExpect(header().string("Cache-Control", containsString("max-age")))
                .andReturn().getResponse().getContentAsByteArray();

        assertThat(QrCodeServiceTest.decode(body)).isEqualTo("http://localhost:8080/" + code);
    }

    @Test
    void theRequestedSizeIsHonoured() throws Exception {
        String code = newLink();
        byte[] body = mvc.perform(get("/api/v1/urls/" + code + "/qr?size=300")).andExpect(status().isOk())
                .andReturn().getResponse().getContentAsByteArray();
        assertThat(javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(body)).getWidth()).isEqualTo(300);
    }

    @Test
    void svgIsServedWithTheSvgMediaType() throws Exception {
        String code = newLink();
        mvc.perform(get("/api/v1/urls/" + code + "/qr?format=SVG&size=200"))
                .andExpect(status().isOk())
                .andExpect(content().contentType("image/svg+xml"))
                .andExpect(content().string(containsString("<svg")))
                .andExpect(content().string(containsString("width=\"200\"")));
    }

    @Test
    void badSizesAndFormatsAreRejected() throws Exception {
        String code = newLink();
        mvc.perform(get("/api/v1/urls/" + code + "/qr?size=" + (QrCodeService.MIN_SIZE - 1))).andExpect(status().isBadRequest());
        mvc.perform(get("/api/v1/urls/" + code + "/qr?size=" + (QrCodeService.MAX_SIZE + 1))).andExpect(status().isBadRequest());
        mvc.perform(get("/api/v1/urls/" + code + "/qr?format=gif")).andExpect(status().isBadRequest());
        mvc.perform(get("/api/v1/urls/" + code + "/qr?size=abc")).andExpect(status().isBadRequest());
    }

    @Test
    void anUnknownCodeIs404() throws Exception {
        mvc.perform(get("/api/v1/urls/nosuchcode/qr")).andExpect(status().isNotFound());
    }

    @Test
    void aDeletedCodeIs410() throws Exception {
        String code = newLink();
        service.delete(code);
        mvc.perform(get("/api/v1/urls/" + code + "/qr")).andExpect(status().isGone());
    }
}
